284	impl ActionRegistry {
285	    /// Load all registered actions into the registry.
286	    pub(crate) fn load_actions(&mut self) {
287	        for builder in inventory::iter::<MacroActionBuilder> {
288	            let action = builder.0();
289	            self.insert_action(action);
290	        }
291	    }
292	
293	    fn insert_action(&mut self, action: MacroActionData) {
294	        let name = action.name;
295	        if self.by_name.contains_key(name) {
296	            panic!(
297	                "Action with name `{name}` already registered \
298	                (might be registered in `#[action(deprecated_aliases = [...])]`."
299	            );
300	        }
301	        self.by_name.insert(
302	            name,
303	            ActionData {
304	                build: action.build,
305	                json_schema: action.json_schema,
306	            },
307	        );
308	        for &alias in action.deprecated_aliases {
309	            if self.by_name.contains_key(alias) {
310	                panic!(
311	                    "Action with name `{alias}` already registered. \
312	                    `{alias}` is specified in `#[action(deprecated_aliases = [...])]` for action `{name}`."
313	                );
314	            }
315	            self.by_name.insert(
316	                alias,
317	                ActionData {
318	                    build: action.build,
319	                    json_schema: action.json_schema,
320	                },
321	            );
322	            self.deprecated_aliases.insert(alias, name);
323	            self.all_names.push(alias);
324	        }
325	        self.names_by_type_id.insert(action.type_id, name);
326	        self.all_names.push(name);
327	        if let Some(deprecation_msg) = action.deprecation_message {
328	            self.deprecation_messages.insert(name, deprecation_msg);
329	        }
330	        if let Some(documentation) = action.documentation {
331	            self.documentation.insert(name, documentation);
332	        }
333	    }
334	
335	    /// Construct an action based on its name and optional JSON parameters sourced from the keymap.
336	    pub fn build_action_type(&self, type_id: &TypeId) -> Result<Box<dyn Action>> {
337	        let name = self
338	            .names_by_type_id
339	            .get(type_id)
340	            .with_context(|| format!("no action type registered for {type_id:?}"))?;
341	
342	        Ok(self.build_action(name, None)?)
343	    }
344	
345	    #[cfg(feature = "profiler")]
346	    pub(crate) fn try_resolve_action(&self, type_id: &TypeId) -> Option<&'static str> {
347	        self.names_by_type_id.get(type_id).copied()
348	    }
349	
350	    /// Construct an action based on its name and optional JSON parameters sourced from the keymap.
351	    pub fn build_action(
352	        &self,
353	        name: &str,
354	        params: Option<serde_json::Value>,
355	    ) -> std::result::Result<Box<dyn Action>, ActionBuildError> {
356	        let build_action = self
357	            .by_name
358	            .get(name)
359	            .ok_or_else(|| ActionBuildError::NotFound {
360	                name: name.to_owned(),
361	            })?
362	            .build;
363	        (build_action)(params.unwrap_or_else(|| json!({}))).map_err(|e| {
364	            ActionBuildError::BuildError {
365	                name: name.to_owned(),
366	                error: e,
367	            }
368	        })
369	    }
370	
371	    pub fn all_action_names(&self) -> &[&'static str] {
372	        self.all_names.as_slice()
373	    }
374	
375	    pub fn action_schemas(
376	        &self,
377	        generator: &mut schemars::SchemaGenerator,
378	    ) -> Vec<(&'static str, Option<schemars::Schema>)> {
379	        // Use the order from all_names so that the resulting schema has sensible order.
380	        self.all_names
381	            .iter()
382	            .map(|name| {
383	                let action_data = self
384	                    .by_name
385	                    .get(name)
386	                    .expect("All actions in all_names should be registered");
387	                (*name, (action_data.json_schema)(generator))
388	            })
389	            .collect::<Vec<_>>()
390	    }
391	
392	    pub fn action_schema_by_name(
393	        &self,
394	        name: &str,
395	        generator: &mut schemars::SchemaGenerator,
396	    ) -> Option<Option<schemars::Schema>> {
397	        self.by_name
398	            .get(name)
399	            .map(|action_data| (action_data.json_schema)(generator))
400	    }
401	
402	    pub fn deprecated_aliases(&self) -> &HashMap<&'static str, &'static str> {
403	        &self.deprecated_aliases
404	    }
405	
406	    pub fn deprecation_messages(&self) -> &HashMap<&'static str, &'static str> {
407	        &self.deprecation_messages
408	    }
409	
410	    pub fn documentation(&self) -> &HashMap<&'static str, &'static str> {
411	        &self.documentation
412	    }
413	}
