415	/// Generate a list of all the registered actions.
416	/// Useful for transforming the list of available actions into a
417	/// format suited for static analysis such as in validating keymaps, or
418	/// generating documentation.
419	pub fn generate_list_of_all_registered_actions() -> impl Iterator<Item = MacroActionData> {
420	    inventory::iter::<MacroActionBuilder>
421	        .into_iter()
422	        .map(|builder| builder.0())
423	}
