430	    actions!(
431	        zed,
432	        [
433	            /// Action with special handling which unbinds the keybinding this is associated with,
434	            /// if it is the highest precedence match.
435	            NoAction
436	        ]
437	    );
438	
439	    /// Action with special handling which unbinds later bindings for the same keystrokes when they
440	    /// dispatch the named action, regardless of that action's context.
441	    ///
442	    /// In keymap JSON this is written as:
443	    ///
444	    /// `["zed::Unbind", "editor::NewLine"]`
445	    #[derive(Clone, Debug, PartialEq, Deserialize, JsonSchema, gpui::Action)]
446	    #[action(namespace = zed)]
447	    pub struct Unbind(pub gpui::SharedString);
448	
449	    /// Returns whether or not this action represents a removed key binding.
450	    pub fn is_no_action(action: &dyn gpui::Action) -> bool {
451	        action.as_any().is::<NoAction>()
452	    }
